const d={input:"work_date"},o={workDate:"work_date",page:"page"},i={enter:"Enter"};document.addEventListener("DOMContentLoaded",()=>{const r=document.getElementById(d.input);if(!(r instanceof HTMLInputElement))return;const e=r,c=t=>{const s=t.trim();try{const a=new URL(window.location.href),n=a.searchParams;s?n.set(o.workDate,s):n.delete(o.workDate),n.delete(o.page),a.search=n.toString(),window.location.href=a.toString()}catch{}};e.addEventListener("change",()=>{c(e.value)}),e.addEventListener("keydown",t=>{t.key===i.enter&&(t.preventDefault(),c(e.value))})});
